using System.Text;
using ApiClientGenerator.Abstractions.Abstractions;
using ApiClientGenerator.Abstractions.Models;
using ApiClientGenerator.Abstractions.Parsing;

namespace ApiClientGenerator.React;

public sealed class TypeScriptRepositoryEmitter(
    ITypeMapper typeMapper,
    INamingConvention naming) : IRepositoryEmitter
{
    public string FileExtension => ".ts";
    public string HttpClientFileName => "http.ts";

    public string EmitHttpClient() =>
        """
        // <auto-generated />
        // Этот файл сгенерирован автоматически. Не редактируйте вручную.

        export const BASE_URL = process.env.REACT_APP_API_URL ?? '';

        let tokenProvider: () => string | null = () => null;

        export function setAuthTokenProvider(fn: () => string | null): void {
          tokenProvider = fn;
        }

        export class ApiError extends Error {
          constructor(public status: number, public body: string) {
            super(`API Error ${status}: ${body}`);
            this.name = 'ApiError';
          }
        }

        export interface RequestOptions {
          query?: Record<string, string | number | boolean | undefined | null>;
          body?: unknown;
          headers?: Record<string, string>;
        }

        export async function httpRequest<T>(
          method: string,
          path: string,
          options: RequestOptions = {}
        ): Promise<T> {
          const query = options.query
            ? '?' + new URLSearchParams(
                Object.entries(options.query)
                  .filter(([, v]) => v !== undefined && v !== null)
                  .map(([k, v]) => [k, String(v)] as [string, string])
              ).toString()
            : '';

          const headers: Record<string, string> = { ...options.headers };
          const token = tokenProvider();
          if (token) headers['Authorization'] = `Bearer ${token}`;
          if (options.body !== undefined) headers['Content-Type'] = 'application/json';

          const response = await fetch(`${BASE_URL}${path}${query}`, {
            method,
            headers,
            body: options.body !== undefined ? JSON.stringify(options.body) : undefined,
          });

          if (!response.ok) {
            const text = await response.text();
            throw new ApiError(response.status, text);
          }

          if (response.status === 204) return undefined as T;

          const contentType = response.headers.get('content-type') ?? '';
          if (contentType.includes('application/json')) {
            return await response.json() as T;
          }
          return await response.text() as unknown as T;
        }
        """;

    public string EmitRepository(
        string tag,
        IReadOnlyList<ParsedEndpoint> endpoints,
        IReadOnlySet<string> localModels,
        string relativeImportPrefix)
    {
        var className = $"{tag}Repository";
        var sb = new StringBuilder();

        sb.AppendLine("// <auto-generated />");
        sb.AppendLine();
        sb.AppendLine($"import {{ httpRequest }} from '{relativeImportPrefix}http';");

        if (localModels.Count > 0)
            sb.AppendLine("import type * as Models from './models';");

        sb.AppendLine();
        sb.AppendLine($"export class {className} {{");

        foreach (var e in endpoints)
        {
            EmitMethod(sb, e, localModels);
            sb.AppendLine();
        }

        sb.AppendLine("}");
        return sb.ToString();
    }

    private void EmitMethod(StringBuilder sb, ParsedEndpoint e, IReadOnlySet<string> localModels)
    {
        var methodName = naming.MethodName(e.OperationId);
        var returnType = ResolveReturnType(e.ResponseBody, localModels);
        var parameters = BuildParameters(e, localModels);
        var pathExpr = BuildPathExpression(e);
        var queryObj = BuildQueryObject(e);

        sb.AppendLine($"  static async {methodName}({parameters}): Promise<{returnType}> {{");
        sb.AppendLine($"    return httpRequest<{returnType}>('{e.Method}', {pathExpr}, {{");

        if (queryObj is not null)
            sb.AppendLine($"      query: {queryObj},");

        if (e.RequestBody is not null)
            sb.AppendLine("      body,");

        sb.AppendLine("    });");
        sb.AppendLine("  }");
    }

    private string BuildParameters(ParsedEndpoint e, IReadOnlySet<string> localModels)
    {
        var parts = new List<string>();

        foreach (var p in e.Parameters.Where(x => x.In == "path"))
        {
            var type = ResolveSchemaType(p.Schema, localModels);
            parts.Add($"{naming.PropertyName(p.Name)}: {type}");
        }

        foreach (var p in e.Parameters.Where(x => x.In == "query"))
        {
            var type = ResolveSchemaType(p.Schema, localModels);
            var optional = p.Required ? "" : "?";
            parts.Add($"{naming.PropertyName(p.Name)}{optional}: {type}");
        }

        if (e.RequestBody is not null)
            parts.Add($"body: {ResolveSchemaType(e.RequestBody, localModels)}");

        return string.Join(", ", parts);
    }

    private string BuildPathExpression(ParsedEndpoint e)
    {
        var path = e.Path;

        foreach (var p in e.Parameters.Where(x => x.In == "path"))
        {
            var name = naming.PropertyName(p.Name);
            var isDate = p.Schema.Format is "date-time" or "date";
            var expr = isDate ? name : $"encodeURIComponent(String({name}))";
            path = path.Replace($"{{{p.Name}}}", $"${{{expr}}}");
        }

        return $"`{path}`";
    }

    private string? BuildQueryObject(ParsedEndpoint e)
    {
        var queryParams = e.Parameters.Where(p => p.In == "query").ToList();
        if (queryParams.Count == 0) return null;

        var entries = queryParams.Select(p =>
        {
            var localName = naming.PropertyName(p.Name);
            var key = p.Name == localName ? p.Name : $"'{p.Name}'";
            return $"{key}: {localName}";
        });

        return $"{{ {string.Join(", ", entries)} }}";
    }

    private string ResolveReturnType(OpenApiSchema? schema, IReadOnlySet<string> localModels) =>
        schema is null ? "void" : ResolveSchemaType(schema, localModels);

    private string ResolveSchemaType(OpenApiSchema schema, IReadOnlySet<string> localModels)
    {
        if (schema.Ref is not null)
        {
            var name = schema.Ref.Split('/')[^1];
            return typeMapper.MapReference(name, localModels.Contains(name));
        }

        if (schema.Enum is { Count: > 0 })
            return "string";

        var baseType = schema.Type switch
        {
            "string" => typeMapper.MapPrimitive("string", schema.Format),
            "integer" or "number" => typeMapper.MapPrimitive(schema.Type, schema.Format),
            "boolean" => typeMapper.MapPrimitive("boolean", schema.Format),
            "array" => schema.Items is not null
                ? typeMapper.MapArray(ResolveSchemaType(schema.Items, localModels))
                : typeMapper.MapArray(typeMapper.MapUnknown()),
            "object" => typeMapper.MapObject(),
            _ => typeMapper.MapUnknown()
        };

        return schema.Nullable ? typeMapper.MakeNullable(baseType) : baseType;
    }
}